SELECT u.id, u.username, u.display_name FROM app_user u WHERE NOT EXISTS ( SELECT 1 FROM workspace_member m WHERE m.workspace_id = #{workspaceId} AND m.user_id = u.id )
AND (LOCATE(LOWER(#{q}), LOWER(u.username)) > 0 OR LOCATE(LOWER(#{q}), LOWER(u.display_name)) > 0)
ORDER BY u.username LIMIT #{limit}

